Certainly! Below is a TypeScript function that takes two arrays as inputs, sorts them, removes duplicates, and then finds the intersection of the two arrays. The function also handles edge cases such as empty arrays and arrays with only non-unique elements.

```typescript
function findCommonElements<T>(arr1: T[], arr2: T[]): T[] {
    if (arr1.length === 0 || arr2.length === 0) {
        return [];
    }

    // Using Set to remove duplicates and sort the arrays
    const set1 = new Set(arr1);
    const set2 = new Set(arr2);
    const sortedUniqueArray1 = Array.from(set1);
    const sortedUniqueArray2 = Array.from(set2);

    // Sort the arrays
    sortedUniqueArray1.sort((a, b) => (a < b ? -1 : 1));
    sortedUniqueArray2.sort((a, b) => (a < b ? -1 : 1));

    let intersection: T[] = [];
    let pointer1 = 0;
    let pointer2 = 0;

    // Find the common elements
    while (pointer1 < sortedUniqueArray1.length && pointer2 < sortedUniqueArray2.length) {
        if (sortedUniqueArray1[pointer1] === sortedUniqueArray2[pointer2]) {
            intersection.push(sortedUniqueArray1[pointer1]);
            pointer1++;
            pointer2++;
        } else if (sortedUniqueArray1[pointer1] < sortedUniqueArray2[pointer2]) {
            pointer1++;
        } else {
            pointer2++;
        }
    }

    return intersection;
}

// Example usage:
