```csharp
using System;

namespace DecimalToBinaryConverter
{
    class Program
    {
        static void Main(string[] args)
        {
            // Display program instructions and welcome message
            Console.WriteLine("Welcome to the Decimal to Binary Converter.");
            Console.WriteLine("This program will convert a decimal number to its binary equivalent.");
            Console.WriteLine("Please enter a decimal number to begin:");

            // Read the user's input from the console
            string input = Console.ReadLine();
            try
            {
                decimal decimalNumber = Convert.ToDecimal(input);

                // Validate the input to ensure it's a positive number
                if (decimalNumber <= 0)
                {
                    throw new ArgumentOutOfRangeException("Input should be a positive number");
                }

                // Convert decimal to binary using loop
                string binaryNumber = ConvertToBinary(decimalNumber);

                // Display the result to the user
                Console.WriteLine($"The binary equivalent of {decimalNumber} is: {binaryNumber}");
            }
            catch (FormatException)
            {
                Console.WriteLine("Error: Input must be a valid decimal number.");
            }
            catch (ArgumentOutOfRangeException exception)
            {
                Console.WriteLine($"Error: {exception.Message}");
            }
            catch (OverflowException)
            {
                Console.WriteLine("Error: The number is too large to convert.");
            }
            catch (Exception exception)
            {
                Console.WriteLine($"An unexpected error occurred: {exception.Message}");
            }
        }

        // Method to convert decimal to binary
        private static string ConvertToBinary(decimal number)
        {
            string binary = "";
            while (number > 0)
            {
                binary = (number % 2) + binary; // Get the remainder and prepend it to the binary string
                number /= 2; // Divide number by 2
            }
            return binary;
        }
    }
}
