```cpp
#include <iostream>
#include <stdexcept>

class Queue {
public:
    // Constructor
    Queue() : head(0), tail(0), size(0) {}

    // Destructor
    ~Queue() {
        while (!isEmpty()) {
            std::cout << "Removing element from queue: " << dequeue() << std::endl;
        }
    }

    // Add element to the end of the queue
    void enqueue(int value) {
        QNode* newNode = new QNode(value);
        if (!newNode) {
            throw std::bad_alloc(); // Handle memory allocation failure
        }

        // If the queue is empty, the new node becomes both head and tail
        if (!head) {
            head = tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }

        size++;
    }

    // Add element to the front of the queue
    void addFront(int value) {
        QNode* newNode = new QNode(value);
        if (!newNode) {
            throw std::bad_alloc(); // Handle memory allocation failure
        }

        newNode->next = head;
        head = newNode;

        size++;
    }

    // Remove element from the front of the queue
    int dequeue() {
        if (isEmpty()) {
            throw std::out_of_range("Queue is empty, cannot dequeue.");
        }

        int value = head->value;
        QNode* temp = head;
        head = head->next;

        if (!head) {
            tail = 0;
        }

        delete temp;
        size--;

        return value;
    }

    // Check if the queue is empty
    bool isEmpty() const {
        return size == 0;
    }

    // Size of the queue
    int getSize() const {
        return size;
    }

private:
    struct QNode {
        int value;
        QNode* next;
        QNode(int val) : value(val), next(0) {}
    };

    QNode* head;
    QNode* tail;
    int size;
};

int main() {
    Queue myQueue;

    try {
        myQueue.enqueue(10);
        myQueue.enqueue(20);
        myQueue.addFront(5);
        myQueue.dequeue(); // Dequeue 5
        myQueue.dequeue(); // Dequeue 10
        myQueue.dequeue(); // Dequeue 20
        myQueue.enqueue(30);
        std::cout << "Size of queue: " << myQueue.getSize() << std::endl;
        myQueue.dequeue(); // Attempt to dequeue from an empty queue
    } catch (const std::exception& e) {
        std::cerr << "Exception occurred: " << e.what() << std::endl;
    }

    return 0;
}
```

### Explanation:
- **Queue Class:**
  - **Constructor:** Initializes the queue.
  - **Destructor:** Handles the case where the queue is empty and all nodes are deleted.
  - **enqueue:** Adds an element to the end of the queue.
  - **addFront:** Adds an element to the front of the queue.
  - **dequeue:** Removes and returns the element from the front of the queue, throwing an exception if the queue is empty.
  - **isEmpty:** Checks if the queue is empty.
  - **getSize:** Returns the size of the queue.

- **QNode Struct:** Represents a single node in the queue, containing an `int` value and a pointer to the next node.

- **Exception Handling:** The `enqueue` and `addFront` methods use `std::bad_alloc` to handle memory allocation failures. The `dequeue` method throws an `std::out_of_range` exception if the queue is empty.

- **Main Function:** Demonstrates the usage of the `Queue` class by enqueueing and dequeuing elements and throwing exceptions to handle empty queue cases correctly.

This implementation follows standard best practices for C++ programming, including exception safety and regular error checking.

