```javascript
// Function to get browser and version information
function getBrowserDetails() {
    const userAgent = navigator.userAgent;
    const browserDetails = {
        isChrome: navigator.userAgent.indexOf('Chrome') > -1,
        isFirefox: navigator.userAgent.indexOf('Firefox') > -1,
        isSafari: navigator.userAgent.indexOf('Safari') > -1,
        isEdge: navigator.userAgent.indexOf('Edge/') > -1,
        isIE: navigator.userAgent.indexOf('MSIE') > -1 || navigator.userAgent.indexOf('Trident/') > -1,
        isOther: false, // This will be set to true if no other browsers match
        browser: 'Other',
        version: 'Unknown'
    };

    // Determine the browser and version based on the user agent string
    if (browserDetails.isChrome) {
        browserDetails.browser = 'Chrome';
        browserDetails.version = parseFloat(userAgent.match(/Chrome\/([0-9]+)\./)[1]);
    } else if (browserDetails.isFirefox) {
        browserDetails.browser = 'Firefox';
        browserDetails.version = parseFloat(userAgent.match(/Firefox\/([0-9]+)\./)[1]);
    } else if (browserDetails.isSafari) {
        browserDetails.browser = 'Safari';
        browserDetails.version = parseFloat(userAgent.match(/Version\/([0-9]+)\./)[1]);
    } else if (browserDetails.isEdge) {
        browserDetails.browser = 'Edge';
        browserDetails.version = parseFloat(userAgent.match(/Edge\/([0-9]+)\./)[1]);
    } else if (browserDetails.isIE) {
        browserDetails.browser = 'Internet Explorer';
        browserDetails.version = parseFloat(userAgent.match(/MSIE ([0-9]+)\./)[1]);
    } else {
        browserDetails.browser = 'Other';
        browserDetails.version = parseFloat(userAgent.match(/Trident\/([0-9]+)\./)[1]);
    }

    // Check to see if any other browser matches
    if (!browserDetails.isChrome && !browserDetails.isFirefox && !browserDetails.isSafari && !browserDetails.isEdge && !browserDetails.isIE) {
        browserDetails.isOther = true;
    }

    return browserDetails;
}

// Function to display the browser and version details
function displayBrowserDetails() {
    const browserDetails = getBrowserDetails();
    let browserInfo;

    if (browserDetails.isOther) {
        browserInfo = browserDetails.browser + ' detected';
    } else {
        browserInfo = browserDetails.browser + ' ' + browserDetails.version;
    }

    // Display the information on the webpage
    const browserList = document.createElement('ul');
    const listItem = document.createElement('li');
    listItem.textContent = `Browser: ${browserInfo}`;
    browserList.appendChild(listItem);

    // Optionally show a bulleted list of browser details
    if (window.innerWidth >= 600) {
        const detailsList = document.createElement('ul');
        const detailItem = document.createElement('li');
        detailItem.textContent = 'User Agent: ' + navigator.userAgent;
        detailsList.appendChild(detailItem);

        const browserItem = document.createElement('li');
        browserItem.textContent = 'Browser: ' + browserDetails.browser;
        detailsList.appendChild(browserItem);

        const versionItem = document.createElement('li');
        versionItem.textContent = 'Version: ' + browserDetails.version;
        detailsList.appendChild(versionItem);

        document.body.appendChild(detailsList);
    }

    document.body.appendChild(browserList);
}

// Function to handle rendering the browser details on page load
document.addEventListener('DOMContentLoaded', () => {
    displayBrowserDetails();
});
```

### Explanation of Key Components:

1. **Function `getBrowserDetails`:**
   - This function uses `navigator.userAgent` to determine the browser and its version. It checks for common strings in the user agent string to identify Chrome, Firefox, Safari, Edge, and Internet Explorer.
   - It matches these keywords and extracts the version number. For Internet Explorer, it uses a different pattern as it does not consistently include the version number in the user agent string.
   - If no specific browser matches, it categorizes the browser as "Other".

2. **Function `displayBrowserDetails`:**
   - This function calls `getBrowserDetails` to get the browser and version information.
   - Based on the result, it constructs an `li` element with the browser details.
   - It optionally displays these details in a bulleted list if the screen width is 600px or more.

3. **Event Listener for Page Load:**
   - The `DOMContentLoaded` event listener ensures that the browser details are displayed only after the DOM has fully loaded.

